// HunterToon JS source for mknov.com (مملكه الروايات)
// Self-contained Arabic novel source using Next.js RSC + per-request protected font decoder.
function createSource(api, config) {
  var baseUrl = ((config && config.base_url) || "https://www.mknov.com").replace(/\/+$/, "");
  var cfgHeaders = (config && config.headers) || {};
  var userAgent =
    cfgHeaders["User-Agent"] ||
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

  var defaultHeaders = {
    "User-Agent": userAgent,
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8",
    "Accept-Language": "ar,en;q=0.9",
    "Referer": baseUrl + "/",
    "Origin": baseUrl,
    "Sec-Fetch-Dest": "document",
    "Sec-Fetch-Mode": "navigate",
    "Sec-Fetch-Site": "same-origin",
    "Upgrade-Insecure-Requests": "1"
  };

  function mergeHeaders(a, b) {
    var out = {};
    if (a) for (var k in a) out[k] = a[k];
    if (b) for (var x in b) out[x] = b[x];
    return out;
  }

  async function fetchHtml(url, extraHeaders, method) {
    var headers = mergeHeaders(defaultHeaders, extraHeaders);
    if (api.http) {
      var res = await api.http(url, { method: method || "GET", headers: headers });
      if (!res || !res.ok) throw new Error("HTTP " + (res ? res.status : 0) + " for " + url);
      return res.body || "";
    }
    var html = await api.fetchText(url, headers);
    if (!html) throw new Error("Empty response: " + url);
    return html;
  }

  function clean(s) { return String(s || "").replace(/\s+/g, " ").trim(); }

  function abs(url) {
    if (!url) return "";
    url = String(url).trim();
    if (url.indexOf("https://") === 0 || url.indexOf("http://") === 0) return url;
    if (url.indexOf("//") === 0) return "https:" + url;
    if (url.charAt(0) === "/") return baseUrl + url;
    return baseUrl + "/" + url;
  }

  // RSC payload extraction: concatenate all self.__next_f.push([1, "..."]) string contents
  function extractRscPayload(html) {
    var startMarker = "self.__next_f.push([";
    var payloads = [];
    var idx = 0;
    while (true) {
      var si = html.indexOf(startMarker, idx);
      if (si === -1) break;
      var arrStart = si + startMarker.length;
      var comma = html.indexOf(",", arrStart);
      if (comma === -1) break;
      var strStart = html.indexOf("\"", comma + 1);
      if (strStart === -1) break;
      strStart += 1;
      var strEnd = -1;
      var esc = false;
      for (var pi = strStart; pi < html.length; pi++) {
        var pc = html.charAt(pi);
        if (esc) { esc = false; continue; }
        if (pc === "\\") { esc = true; continue; }
        if (pc === "\"") { strEnd = pi; break; }
      }
      if (strEnd === -1) break;
      var content = html.substring(strStart, strEnd);
      content = content.replace(/\\"/g, '"').replace(/\\\\/g, "\\").replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t");
      payloads.push(content);
      idx = strEnd + 1;
    }
    return payloads.join("");
  }

  // Balance-bracket extractor (counts `{`/`}` or `[`/`]` outside strings, handles escapes)
  function extractBalanced(str, startPos, openChar, closeChar) {
    var depth = 0;
    var inStr = false;
    var esc = false;
    var end = -1;
    for (var i = startPos; i < str.length; i++) {
      var c = str.charAt(i);
      if (esc) { esc = false; continue; }
      if (c === "\\") { esc = true; continue; }
      if (c === "\"") { inStr = !inStr; continue; }
      if (!inStr) {
        if (c === openChar) { depth++; if (depth === 1 && i !== startPos) return null; }
        else if (c === closeChar) { depth--; if (depth === 0) { end = i + 1; break; } }
      }
    }
    if (end === -1) return null;
    return str.substring(startPos, end);
  }

  function extractJsonValueAt(str, marker, posOffset) {
    var idx = str.indexOf(marker);
    if (idx === -1) return null;
    var start = idx + marker.length + (posOffset || 0);
    while (start < str.length && /\s/.test(str.charAt(start))) start++;
    var ch = str.charAt(start);
    if (ch === "{") return extractBalanced(str, start, "{", "}");
    if (ch === "[") return extractBalanced(str, start, "[", "]");
    return null;
  }

  // Locate row text in payload: e.g. row "18:T" or "18:T1fded,..."
  function findRowText(rsc, rowKey) {
    // Find "\n<rowKey>:" boundary
    var idx = rsc.indexOf("\n" + rowKey + ":");
    if (idx === -1) return "";
    var start = idx + 1 + rowKey.length + 1; // skip "\n" + key + ":"
    // find end: next "\n<digit><maybe letter>:" or end of payload
    var end = rsc.length;
    var re = /\n\d+[a-z]?:/g;
    re.lastIndex = start;
    var m = re.exec(rsc);
    if (m) end = m.index;
    return rsc.slice(start, end);
  }

  // Strip the leading T<hex>, hex-length prefix from a text row (returns content)
  function stripTHeader(text) {
    var m = text.match(/^T[0-9a-fA-F]+,/);
    if (!m) return text;
    return text.slice(m[0].length);
  }

  // Decode scrambled text using per-font MAP (flat object: scrambled_char -> real_char_or_empty).
  // .empty-mapped entries in the map are stored as "" so adding them drops the char.
  // fontN: integer font number (from ArabicProtected-N in page HTML). null = use identity.
  function decodeScramble(text, fontN) {
    if (text == null) return "";
    var mp = fontN != null && typeof MK_DECODERS !== "undefined" ? MK_DECODERS[fontN] : null;
    if (!mp) return text;
    var s = "";
    for (var i = 0; i < text.length; i++) {
      var ch = text.charAt(i);
      var mapped = mp[ch];
      s += (mapped != null) ? mapped : ch;
    }
    return s;
  }

  // Resolve a $NN reference inside a T row text: if text starts with "$18" replace with decoded row 18.
  function resolveRef(text, rsc, fontN) {
    if (!text || text.charAt(0) !== "$") return text;
    var refKey = text.slice(1);
    var rowText = findRowText(rsc, refKey);
    rowText = stripTHeader(rowText);
    return decodeScramble(rowText, fontN);
  }

  // Read font number from a chapter/detail HTML (the inline @font-face ArabicProtected-N)
  function detectFontNumber(html) {
    if (!html) return null;
    var m = html.match(/ArabicProtected-(\d+)/);
    if (!m) return null;
    var n = parseInt(m[1], 10);
    if (isNaN(n)) return null;
    return n;
  }

  // Build a card object from a work object (id, slug, titleAr, image, etc.)
  function buildCard(item) {
    if (!item) return null;
    var slug = item.slug != null ? String(item.slug) : "";
    var id = item.id != null ? String(item.id) : "";
    var title = clean(item.titleAr || item.title || "");
    if (!title) return null;
    var cover = abs(item.image || item.cover || "");
    var status = clean(item.status || "");
    var totalChapters = item.totalChapters != null ? item.totalChapters : 0;
    var detail = slug ? (baseUrl + "/novel/" + slug) : (id ? (baseUrl + "/novel/" + id) : "");
    if (!detail) return null;
    return {
      title: title,
      coverUrl: cover,
      detailUrl: detail,
      contentType: "novel",
      status: status,
      rating: "",
      totalChapters: totalChapters
    };
  }

  // Parse work array from a JSON string and dedupe
  function parseWorkArray(json) {
    if (!json) return [];
    try { return JSON.parse(json); } catch (e) { return []; }
  }

  function dedupeCards(arr) {
    var seen = {};
    var out = [];
    for (var i = 0; i < arr.length; i++) {
      var c = buildCard(arr[i]);
      if (!c || seen[c.detailUrl]) continue;
      seen[c.detailUrl] = true;
      out.push(c);
    }
    return out;
  }

  // Find and parse "featured":[...] or "donghuaList":[...] from RSC payload
  function parseWorkListFromRsc(rsc, key) {
    var marker = '"' + key + '":';
    var i = rsc.indexOf(marker);
    if (i === -1) return [];
    var arrStart = rsc.indexOf("[", i + marker.length);
    if (arrStart === -1) return [];
    var listStr = extractBalanced(rsc, arrStart, "[", "]");
    return parseWorkArray(listStr);
  }

  // Fetch and parse homepage
  async function getHomepageCards(page) {
    var url = page && page > 1 ? baseUrl + "/?page=" + page : baseUrl + "/";
    var html = await fetchHtml(url);
    var rsc = extractRscPayload(html);
    var items = parseWorkListFromRsc(rsc, "featured");
    return dedupeCards(items);
  }

  // Search: /library?q=<query>
  async function getSearchCards(query) {
    if (!query || !query.trim()) return [];
    var url = baseUrl + "/library?q=" + encodeURIComponent(query.trim());
    var html = await fetchHtml(url);
    var rsc = extractRscPayload(html);
    var items = parseWorkListFromRsc(rsc, "donghuaList");
    return dedupeCards(items);
  }

  // Parse novel detail page: extract WorkHero props (row 18) and WorkChapters props (row 21)
  // Description is $19 reference; Episodes (first 5) inline; full chapters via API.
  async function getNovelDetail(detailUrl) {
    var html = await fetchHtml(detailUrl);
    var rsc = extractRscPayload(html);
    var fontN = detectFontNumber(html);

    // Row 18 contains WorkHero props like: {"donghua":{"id":...,...},"$L1a"}
    // We need the donghua object specifically.
    var row18 = findRowText(rsc, "18");
    row18 = stripTHeader(row18);
    var donghua = null;
    var dongMarker = '"donghua":{';
    var di = row18.indexOf(dongMarker);
    if (di !== -1) {
      var arrStart = di + dongMarker.length - 1; // point to {
      var dongStr = extractBalanced(row18, arrStart, "{", "}");
      if (dongStr) {
        try { donghua = JSON.parse(dongStr); } catch (e) {}
      }
    }

    if (!donghua) {
      // Fallback: parse og meta tags
      var ogTitle = await api.cssAttr(html, "meta[property='og:title']", "content") || "";
      var ogImg = await api.cssAttr(html, "meta[property='og:image']", "content") || "";
      var ogDesc = await api.cssAttr(html, "meta[property='og:description']", "content") || "";
      var slugMatch = String(detailUrl).match(/\/novel\/(\d+)/);
      donghua = {
        id: slugMatch ? slugMatch[1] : "",
        slug: slugMatch ? slugMatch[1] : "",
        titleAr: clean(ogTitle).replace(/\s*\|.*$/, "").trim(),
        title: clean(ogTitle),
        author: "", translator: "", genres: [], year: 0, totalChapters: 0, status: "",
        description: clean(ogDesc),
        image: ogImg, totalViews: 0
      };
    }

    var card = buildCard(donghua);
    if (!card) {
      card = { title: "Unknown", coverUrl: "", detailUrl: detailUrl, contentType: "novel", status: "", rating: "" };
    }

    // Resolve description: may be "$19" reference (resolved via row 19 T text + decode)
    var descRef = donghua && donghua.description;
    var desc = "";
    if (descRef && typeof descRef === "string" && descRef.charAt(0) === "$") {
      desc = resolveRef(descRef, rsc, fontN);
    } else if (typeof descRef === "string") {
      desc = descRef;
    } else {
      desc = "";
    }

    // Resolve genres (list of strings)
    var genres = [];
    if (donghua && Array.isArray(donghua.genres)) {
      for (var gi = 0; gi < donghua.genres.length; gi++) {
        var g = clean(donghua.genres[gi]);
        if (g) genres.push(g);
      }
    }

    var author = clean(donghua && (donghua.author || "") || "");
    var translator = clean(donghua && (donghua.translator || "") || "");
    var titleAlt = clean(donghua && (donghua.title || "") || "");
    var year = donghua && donghua.year != null ? donghua.year : 0;
    var totalChapters = donghua && donghua.totalChapters != null ? donghua.totalChapters : 0;

    return {
      title: card.title,
      coverUrl: card.coverUrl,
      description: desc,
      genres: genres,
      status: card.status,
      author: author,
      translator: translator,
      alternateTitle: titleAlt,
      year: year,
      totalChapters: totalChapters,
      originalUrl: detailUrl,
      chapters: [],
      hasMoreChapters: false,
      lastFetchedPage: 0,
      contentType: "novel"
    };
  }

  // Fetch full chapter list via API
  async function getChapterList(workId) {
    if (!workId) return [];
    var url = baseUrl + "/api/works/" + encodeURIComponent(workId) + "/chapters";
    var json = await fetchHtml(url, null, "GET");
    try {
      var data = JSON.parse(json);
    } catch (e) { return []; }
    var volumes = data && data.volumes;
    if (!Array.isArray(volumes)) return [];
    var out = [];
    for (var vi = 0; vi < volumes.length; vi++) {
      var v = volumes[vi];
      var vnum = v.volumeNumber != null ? v.volumeNumber : 1;
      var vtitle = v.title || "";
      var chs = v.chapters || [];
      for (var ci = 0; ci < chs.length; ci++) {
        var c = chs[ci];
        var num = c.chapterNumber != null ? c.chapterNumber : 0;
        var cid = c.id != null ? String(c.id) : "";
        if (!cid) continue;
        out.push({
          number: String(num),
          title: clean(c.chapterTitle || "الفصل " + num),
          url: baseUrl + "/novel/" + encodeURIComponent(workId) + "/chapter/" + encodeURIComponent(cid),
          chapterId: cid,
          volume: vnum,
          volumeTitle: vtitle,
          date: clean(c.publishDate || ""),
          views: c.views != null ? c.views : 0,
          isLocked: false
        });
      }
    }
    // sort desc by number
    out.sort(function (a, b) { return (parseInt(b.number, 10) || 0) - (parseInt(a.number, 10) || 0); });
    return out;
  }

  // Fetch and decode chapter text content
  async function getChapterContent(chapterUrl) {
    if (!chapterUrl) return { kind: "text", chapterTitle: "", textContent: "" };
    var html = await fetchHtml(chapterUrl);
    var fontN = detectFontNumber(html);
    var rsc = extractRscPayload(html);

    // The chapter content is in row 18:T<hex>,<scrambled text>
    var row18 = findRowText(rsc, "18");
    // Some pushes end the row header only; concatenation still includes the content.
    var content = stripTHeader(row18);
    content = decodeScramble(content, fontN);

    // Try to extract chapter title: clean <title> from HTML (it's always plain, not scrambled)
    var titleMatch = html.match(/<title>([^<]*)<\/title>/i);
    var chapterTitle = "";
    if (titleMatch) {
      // title looks like: "الفصل 335 من رواية ... | مملكه الروايات"
      var t = clean(titleMatch[1]);
      // Keep only the "الفصل X: ..." part or trim the trailing site name
      var dash = t.indexOf(" | ");
      if (dash > 0) t = t.slice(0, dash);
      chapterTitle = t;
    }
    // Also extract work_title and chapter_title from meta tags if present
    var metaTitle = await api.cssAttr(html, "meta[property='og:title']", "content");
    if (metaTitle && !chapterTitle) chapterTitle = clean(metaTitle);

    return { kind: "text", chapterTitle: chapterTitle, textContent: content };
  }

  return {
    requiresCloudflare: false,

    async getHomepageManga(args) {
      try {
        var page = (args && args.page) || 1;
        return await getHomepageCards(page);
      } catch (e) { return []; }
    },

    async search(args) {
      try {
        var q = (args && args.query) || "";
        if (!q.trim()) return [];
        return await getSearchCards(q);
      } catch (e) { return []; }
    },

    async getMangaDetails(args) {
      try {
        var url = abs((args && args.url) || "");
        var detail = await getNovelDetail(url);
        // Fetch chapters via API
        var workIdMatch = String(url).match(/\/novel\/(\d+)/);
        var workId = workIdMatch ? workIdMatch[1] : "";
        if (workId) {
          detail.chapters = await getChapterList(workId);
          detail.lastFetchedPage = 1;
          detail.hasMoreChapters = false;
        }
        return detail;
      } catch (e) {
        return {
          title: "Error", coverUrl: "", description: "", genres: [], status: "",
          chapters: [], originalUrl: (args && args.url) || "",
          hasMoreChapters: false, lastFetchedPage: 0, contentType: "novel"
        };
      }
    },

    async fetchMoreChapters() { return null; },

    async getChapterPages() { return []; },

    async getChapterContent(args) {
      try {
        var url = abs((args && args.url) || "");
        return await getChapterContent(url);
      } catch (e) {
        return { kind: "text", chapterTitle: "", textContent: "" };
      }
    },

    async getGenresAndTypes() {
      return { genres: [], types: ["novel"] };
    },

    getImageHeaders() {
      return {
        "User-Agent": userAgent,
        "Referer": baseUrl + "/",
        "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
        "Accept-Language": "ar,en;q=0.9",
        "Sec-Fetch-Dest": "image",
        "Sec-Fetch-Mode": "no-cors",
        "Sec-Fetch-Site": "same-origin"
      };
    },

    sanitizeCoverUrl(args) { return abs((args && args.url) || ""); }
  };
}

// Embedded decode tables for mknov per-request protected fonts (ArabicProtected-0 .. -19)
// Flat map: each key is a scrambled codepoint used in extracted text; the value is either
// the real Arabic letter that the protected font renders for that codepoint, or "" for
